function (values, time, ctx) {
  // ---------- SETTINGS ----------
  var WINDOW_MS   = 20000;       // how much history to show (ms)
  var SMOOTH_MS   = 300;         // moving-average window (ms) smoothing the lines and the values (0 = off)
  var LABELS      = ['', '', ''];// per-line label ('' = column name)
  var MULTIPLIERS = [1, 0.01, 1];   // per-line value scaling (cm -> m = 0.01, m/s -> km/h = 3.6); applies to the line, the axis and the value
  var DIGITS      = 1;           // decimal places of the displayed values
  var UNIT        = '';          // unit text after the values ('' = none)
  var LINE_COLORS = ['#00ff00', '#4da6ff', '#f2a93b']; // line 1, 2, 3 colors
  var LINE_WIDTH  = 2;           // at the default 400x150 size; scales with the widget
  var BG          = 'rgba(0,0,0,.4)';
  var RADIUS      = 8;           // corner radius at the default size; scales with the widget
  var TEXT_COLOR  = '#fff';
  var FONT_SIZE   = 17;          // text size at the default 400x150 size; scales with the widget
  var SCALE       = 'flight';    // 'flight' = axis from whole-flight min/max of all lines (no jumping),
                                 // 'window' = autoscale to visible history, 'fixed' = use MIN/MAX only
  var MIN         = null;        // axis minimum: a number overrides the axis in EVERY mode (null = auto from SCALE)
  var MAX         = 200;         // axis maximum: a number overrides the axis in EVERY mode (null = auto from SCALE)
  var SHOW_GRID   = true;
  // -------------------------------
  var scale = Math.min(ctx.width / 400, ctx.height / 150);  // sizes scale with the widget (settings are for the default 400x150)
  var fsz = FONT_SIZE * scale, lw = LINE_WIDTH * scale;
  var W = ctx.width, H = ctx.height, pad = 6 * scale;
  var t0 = time - WINDOW_MS, t1 = time;
  var nCols = Math.min(3, ctx.columns.length);

  function buildPts(col, cur, m) {
    var pts, j;
    if (SMOOTH_MS > 0) {
      // centered moving average over a slightly wider raw window (sliding-window sum, O(n))
      var raw = ctx.range(col, t0 - SMOOTH_MS / 2, t1 + SMOOTH_MS / 2, 340);
      pts = [];
      var lo = 0, hi = 0, sum = 0, cnt = 0;
      for (j = 0; j < raw.length; j++) {
        var tj = raw[j].t;
        while (hi < raw.length && raw[hi].t <= tj + SMOOTH_MS / 2) { if (typeof raw[hi].v === 'number') { sum += raw[hi].v; cnt++; } hi++; }
        while (lo < raw.length && raw[lo].t < tj - SMOOTH_MS / 2) { if (typeof raw[lo].v === 'number') { sum -= raw[lo].v; cnt--; } lo++; }
        pts.push({ t: tj, v: cnt > 0 ? sum / cnt : raw[j].v });
      }
    } else {
      pts = ctx.range(col, t0, t1, 300);
      // range ends at the last sample <= time; add the interpolated current value so the
      // right end reaches the window edge instead of jumping when a new sample arrives
      if (typeof cur === 'number' && (!pts.length || pts[pts.length - 1].t < t1)) pts.push({ t: t1, v: cur });
    }
    // per-line unit conversion, so lines in different raw units share one axis
    if (m !== 1) pts = pts.map(function (p) { return { t: p.t, v: typeof p.v === 'number' ? p.v * m : p.v }; });
    // pts overhang the window; replace the overhang with points interpolated exactly at the
    // window edges, otherwise both line ends visibly jump as points enter and leave the window
    var out = [], i, p, q;
    for (i = 0; i < pts.length; i++) {
      p = pts[i];
      if (p.t < t0) {
        q = pts[i + 1];
        if (q && q.t > t0 && typeof p.v === 'number' && typeof q.v === 'number')
          out.push({ t: t0, v: p.v + (q.v - p.v) * (t0 - p.t) / (q.t - p.t) });
      } else if (p.t > t1) {
        q = pts[i - 1];
        if (q && q.t < t1 && typeof p.v === 'number' && typeof q.v === 'number')
          out.push({ t: t1, v: q.v + (p.v - q.v) * (t1 - q.t) / (p.t - q.t) });
        break;
      } else out.push(p);
    }
    return out;
  }

  var series = [], s;
  for (s = 0; s < nCols; s++) {
    var mul = (typeof MULTIPLIERS[s] === 'number') ? MULTIPLIERS[s] : 1;
    series.push({
      col: ctx.columns[s],
      color: LINE_COLORS[s] || '#fff',
      label: LABELS[s] || ctx.columns[s],
      m: mul,
      pts: buildPts(ctx.columns[s], values[s], mul)
    });
  }

  // shared min/max across all lines
  var min = Infinity, max = -Infinity;
  if (SCALE === 'flight') {
    for (s = 0; s < series.length; s++) {
      var st = ctx.stats(series[s].col);
      if (st) {
        var a = st.min * series[s].m, b = st.max * series[s].m;  // negative multiplier swaps min/max
        if (Math.min(a, b) < min) min = Math.min(a, b);
        if (Math.max(a, b) > max) max = Math.max(a, b);
      }
    }
  } else if (SCALE === 'window') {
    for (s = 0; s < series.length; s++) series[s].pts.forEach(function (p) {
      if (typeof p.v === 'number') { if (p.v < min) min = p.v; if (p.v > max) max = p.v; }
    });
  }
  // 'fixed' computes nothing and relies on MIN/MAX entirely
  // numeric MIN/MAX override the computed axis in every mode
  if (typeof MIN === 'number') min = MIN;
  if (typeof MAX === 'number') max = MAX;
  if (!isFinite(min)) min = 0;
  if (!isFinite(max)) max = min + 1;
  if (max === min) max = min + 1;

  var grid = '';
  if (SHOW_GRID) for (var i = 1; i < 4; i++) grid += '<line class="grid" x1="0" x2="' + W + '" y1="' + (H * i / 4) + '" y2="' + (H * i / 4) + '" stroke="rgba(255,255,255,.15)" stroke-width="' + Math.max(0.5, scale).toFixed(2) + '"/>';

  var lines = '', legend = '';
  for (s = 0; s < series.length; s++) {
    var sr = series[s], coords = [];
    sr.pts.forEach(function (p) {
      if (typeof p.v !== 'number') return;
      var x = (p.t - t0) / WINDOW_MS * W;
      var y = H - pad - (p.v - min) / (max - min) * (H - 2 * pad);
      coords.push(x.toFixed(1) + ',' + y.toFixed(1));
    });
    if (coords.length > 1) lines += '<polyline class="line line' + (s + 1) + '" points="' + coords.join(' ') + '" fill="none" stroke="' + sr.color + '" stroke-width="' + lw.toFixed(2) + '" stroke-linejoin="round"/>';
    var v = (typeof values[s] === 'number') ? values[s] * sr.m : values[s];
    if (SMOOTH_MS > 0 && typeof v === 'number' && sr.pts.length) v = sr.pts[sr.pts.length - 1].v;  // show the smoothed value too (pts are already converted)
    legend += (s ? '<tspan dx="' + (12 * scale).toFixed(1) + '">' : '<tspan>') + sr.label + ': </tspan><tspan class="value" fill="' + sr.color + '">'
      + (typeof v === 'number' ? v.toFixed(DIGITS) + (UNIT ? ' ' + UNIT : '') : '--') + '</tspan>';
  }

  // CSS hooks: #graph (svg), .grid, .line, .line1, .line2, .line3, .label, .value
  return '<svg id="graph" width="' + W + '" height="' + H + '" style="background:' + BG + ';border-radius:' + (RADIUS * scale).toFixed(1) + 'px">' + grid + lines
    + '<text class="label" x="' + (8 * scale).toFixed(1) + '" y="' + (fsz + 4 * scale).toFixed(1) + '" fill="' + TEXT_COLOR + '" font-family="Arial" font-size="' + fsz.toFixed(1) + '" style="text-shadow:0 0 4px #000">' + legend + '</text></svg>';
}
